mapper.select:
        SELECT


--         级联表的字段
        ,task.task_uuid_number as taskUuidNumber
        ,task.yonghu_id as taskYonghuId
        ,task.task_name as taskName
        ,task.task_money as taskMoney
        ,task.task_status_types as taskStatusTypes
        ,task.task_content as taskContent
        ,errands.errands_name as errandsName
        ,errands.errands_photo as errandsPhoto
        ,errands.errands_phone as errandsPhone
        ,errands.errands_email as errandsEmail
        ,errands.errands_delete as errandsDelete

        FROM orderreceiving  a
        left JOIN task task ON a.task_id = task.id
        left JOIN errands errands ON a.errands_id = errands.id



                and a.id in

                #{item}



                and (
                    a.task_id = #{params.taskId}
                )


                and task.yonghu_id = #{params.yonghuId}


                and (
                a.errands_id = #{params.errandsId}
                )


                and a.orderreceiving_status_types = #{params.orderreceivingStatusTypes}




                and a.task_id IS NOT NULL


                and task.task_uuid_number like CONCAT('%',#{params.taskUuidNumber},'%')


                and task.task_name like CONCAT('%',#{params.taskName},'%')


                  and task.task_money >= #{params.taskMoneyStart}   


                  and task.task_money <= #{params.taskMoneyEnd}   


                and task.task_status_types = #{params.taskStatusTypes}



                and task.task_content like CONCAT('%',#{params.taskContent},'%')



                and a.errands_id IS NOT NULL


                and errands.errands_name like CONCAT('%',#{params.errandsName},'%')


                and errands.errands_phone like CONCAT('%',#{params.errandsPhone},'%')


                and errands.errands_email like CONCAT('%',#{params.errandsEmail},'%')


                  and errands.errands_delete >= #{params.errandsDeleteStart}   


                  and errands.errands_delete <= #{params.errandsDeleteEnd}   


                and errands.errands_delete = #{params.errandsDelete}



        order by a.${params.orderBy} desc
